      "TXT": {
        "name": "TXT — Văn Bản",
        "desc": "Lưu trữ dữ liệu văn bản tùy ý. Được sử dụng rộng rãi cho SPF (chính sách người gửi email), khóa công khai DKIM, chính sách DMARC, xác minh quyền sở hữu tên miền và phản hồi thử thách ACME DNS-01."
      },
      "CAA": {
        "name": "CAA — Ủy Quyền CA",
        "desc": "Chỉ định Cơ quan chứng nhận nào được phép cấp chứng chỉ TLS cho tên miền. Ngăn chặn chứng chỉ được cấp sai. Được các CA kiểm tra trước khi ký — không được trình duyệt thực thi trực tiếp."
      }
