    "polarity_type": "Cực tính",
    "type_prefix": "Loại ",
    "polarity_desc_A": "Cáp thẳng (Straight-through). Key-up ở đầu A, key-down ở đầu B. Việc lật đầu nối ở đầu B làm đảo ngược hàng sợi quang — vị trí n ở đầu A sẽ đến vị trí (tổng+1−n) ở đầu B.",
    "polarity_desc_B": "Cáp đảo ngược (key-up sang key-up). Vị trí sợi quang n ở đầu A tương ứng trực tiếp với vị trí n ở đầu B. Được sản xuất với một đầu nối lật bên trong để triệt tiêu sự đảo ngược hàng.",
    "polarity_desc_C": "Cáp hoán đổi cặp liền kề. Key-up ở đầu A, key-down ở đầu B. Các cặp sợi quang liên tiếp được hoán đổi trước khi lật đầu nối cuối — được sử dụng khi các mô-đun cassette yêu cầu căn chỉnh lại cặp.",
