    "sysctl_subtitle": "Tạo các lệnh sysctl để tinh chỉnh bộ đệm TCP Linux và kiểm soát tắc nghẽn cho các tham số đường truyền của bạn.",
    "sysctl_algo": "Thuật toán kiểm soát tắc nghẽn",
    "sysctl_apply_hint": "Áp dụng bằng: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. Các giá trị được tính toán từ BDP của bạn.",
    "ref_title": "Tham chiếu thuật toán",
    "ref_reno_desc": "Thuật toán AIMD cổ điển. Slow start tăng gấp đôi cwnd mỗi RTT cho đến ssthresh. Congestion avoidance thêm ~1 phân đoạn mỗi RTT. Khi có 3 ACK trùng lặp: ssthresh = cwnd/2, cwnd = ssthresh. Khi timeout: cwnd = 1 MSS. Công bằng nhưng sử dụng kém các đường truyền BDP cao sau khi mất gói.",
    "ref_cubic_desc": "Mặc định trong Linux. Sử dụng hàm bậc ba W(t) = C(t-K)^3 + W_max (C=0,4, beta=0,7). Sau khi mất gói, cwnd giảm xuống 70% của W_max, sau đó tăng qua đường cong lõm-lồi. Mạnh mẽ hơn Reno trên các mạng long-fat. K = (W_max * 0,3 / C)^(1/3).",
    "ref_bbr_desc": "Thuật toán dựa trên mô hình của Google. Ước tính băng thông thắt nút và RTT tối thiểu thay vì sử dụng mất gói làm tín hiệu. Các giai đoạn: Startup (tăng 2,89x), Drain, ProbeBW (chu kỳ tăng 8 giai đoạn: 1,25/0,75/1...), ProbeRTT (4 phân đoạn mỗi ~10 giây). Đạt thông lượng đầy đủ ngay cả khi có mất gói.",
