    "desc_overlay": "Overlay đa host sử dụng đóng gói VXLAN — yêu cầu Docker Swarm. Container trên các host khác nhau xuất hiện trên cùng một phân đoạn L2.",
    "desc_macvlan": "Mỗi container nhận MAC và IP riêng trực tiếp trên phân đoạn L2 của NIC cha. Không NAT, không bridge. Tuyệt vời cho các ứng dụng cũ yêu cầu truy cập L2 trực tiếp.",
    "desc_ipvlan": "Tương tự MACVLAN nhưng tất cả các container chia sẻ MAC cha. Chế độ L3 định tuyến IP container — loại bỏ rủi ro bão ARP trên các triển khai lớn.",
    "desc_host": "Container chia sẻ trực tiếp không gian tên mạng của host — không cô lập, hiệu năng tối đa. Sử dụng cho các tác vụ nhạy cảm với độ trễ như agent giám sát.",
    "desc_none": "Không có giao diện mạng ngoại trừ loopback. Cô lập mạng hoàn toàn. Sử dụng khi container không cần bất kỳ quyền truy cập mạng nào.",
