    "proto_sftp": "SFTP (FTP bảo mật)",
    "proto_tftp": "TFTP (Trivial FTP)",
    "proto_ftp": "FTP (truyền tệp)",
    "proto_http": "HTTP (máy chủ web)",
    "proto_https": "HTTPS (web bảo mật)",
    "proto_scp_notes": "Giao thức Secure Copy. Tải CPU cao trên các thiết bị mạng cũ do mã hóa SSH.",
    "proto_sftp_notes": "Giao thức truyền tệp SSH. Phương thức truyền bảo mật tiêu chuẩn. Chậm hơn SCP một chút do lưu lượng trao đổi của giao thức.",
    "proto_tftp_notes": "Trivial FTP. Truyền theo từng khối kiểu lockstep. Bị giới hạn nặng bởi độ trễ. Kích thước khối tiêu chuẩn giới hạn ở khoảng 1,5 - 3,5 Mbps.",
    "proto_ftp_notes": "Giao thức truyền tệp. Chi phí rất thấp, nhanh nhưng không mã hóa. Thông tin xác thực được truyền dưới dạng văn bản rõ.",
    "proto_http_notes": "Giao thức truyền siêu văn bản. Nhanh, chi phí thấp. Rất phù hợp cho máy chủ dàn dựng cục bộ.",
    "proto_https_notes": "HTTP bảo mật. Tiêu chuẩn cho tải xuống ZTP / đám mây hiện đại. Chi phí mã hóa trung bình.",
    "plat_iosxe": "Cisco IOS / IOS-XE",
    "plat_iosxr": "Cisco IOS-XR",
    "plat_nxos": "Cisco NX-OS",
    "plat_junos": "Juniper Junos",
    "plat_eos": "Arista EOS",
    "plat_fortios": "Fortinet FortiOS",
    "plat_panos": "Palo Alto PAN-OS",
    "plat_linux": "Linux (curl / wget / scp)",
    "plat_f5": "F5 BIG-IP",
    "plat_huawei": "Huawei VRP",
    "plat_iosxe_notes": "Sử dụng \"show flash:\" để đảm bảo hệ thống tệp flash có đủ dung lượng trống. Nếu sử dụng SCP, phải cấu hình \"ip scp server enable\" trên máy chủ, hoặc thiết bị phải bật định tuyến SSH.",
    "plat_iosxr_notes": "Hệ thống tệp IOS-XR dùng disk0: hoặc disk1: thay vì flash:. Lệnh SCP/SFTP trong XR sẽ hỏi mật khẩu người dùng theo dạng tương tác. Ngữ cảnh định tuyến (VRF) có thể cấu hình toàn cục.",
    "plat_nxos_notes": "NX-OS dùng bootflash: theo mặc định. Kiểm tra dung lượng hệ thống tệp bằng \"dir bootflash:\". VRF phải có khả năng tiếp cận IP tới máy chủ; hãy kiểm tra định tuyến mặc định hoặc VRF quản trị.",
    "plat_junos_notes": "Các tệp được sao chép trên Junos được đặt trong /var/tmp/ hoặc /var/db/config/. Dùng \"show system storage\" để kiểm tra dung lượng đĩa. Truyền TFTP có thể yêu cầu cấu hình giao thức định tuyến Junos hoặc dùng từ khóa routing-instance.",
    "plat_eos_notes": "Thiết bị Arista dùng flash:. Xác minh bằng \"dir flash:\". Để có thông lượng cao, Arista hỗ trợ sao chép HTTP/HTTPS gốc được tối ưu hóa cao.",
    "plat_fortios_notes": "Khôi phục TFTP của FortiOS thay thế ảnh khởi động và tự động khởi động lại thiết bị. Hãy sử dụng cẩn trọng. Luôn lưu tệp cấu hình trước đó.",
    "plat_panos_notes": "Palo Alto PAN-OS yêu cầu quyền quản trị CLI rõ ràng để chạy các lệnh nhập phần mềm. Phần mềm cũng có thể được tải xuống trực tiếp từ các bản cập nhật hỗ trợ chính thức của Palo Alto.",
    "plat_linux_notes": "Kiểm tra quyền đọc/ghi của thư mục đích. Đảm bảo máy khách (scp, curl) đã được cài đặt. Truyền HTTP/HTTPS qua curl/wget có thể song song hóa cao.",
    "plat_f5_notes": "Kiểm tra tiến trình bigstart và quyền định tuyến quản trị của F5. Thư mục đích /shared/images/ là vị trí mặc định cho các tệp ISO của F5.",
    "cmd_iosxe": "! Lệnh Cisco IOS/IOS-XE",
    "cmd_iosxr_scp": "! Lệnh Cisco IOS-XR (Lưu ý: máy khách scp/sftp yêu cầu cấu hình máy khách ssh)",
    "cmd_iosxr": "! Lệnh Cisco IOS-XR",
