    "outside_global_sim_hint": "IP đích cho mô phỏng",
    "randomize_ip": "Ngẫu nhiên",
    "double_nat_title": "NAT kép trong triển khai CGNAT",
    "double_nat_body": "Trong một triển khai CGNAT điển hình, người đăng ký cũng thực hiện NAT trên CPE của họ — chuyển đổi các địa chỉ {rfc1918} sang địa chỉ 100.64.0.0/10 được chỉ định trước khi lưu lượng truy cập đến NAT của nhà mạng. NAT kép này phá vỡ UPnP và ánh xạ cổng tự động, làm phức tạp việc chuyển tiếp cổng thủ công và là một điểm yếu đã biết đối với chơi game, VoIP và bất kỳ ứng dụng nào yêu cầu kết nối đến.",
    "hosts_hint": "Các máy chủ bên trong được mô phỏng (bị giới hạn bởi kích thước pool cục bộ)",
    "subscribers_hint": "Người đăng ký / CPE được mô phỏng — mỗi người được chỉ định một khối cổng riêng biệt từ pool công cộng",
    "mode_desc_static": "Liên kết 1:1 vĩnh viễn — mỗi máy chủ bên trong ánh xạ tới một IP công cộng riêng biệt. Đã bật quyền truy cập hai chiều.",
    "mode_desc_dynamic": "Cấp phát pool theo nguyên tắc ai đến trước được phục vụ trước. Các cổng không bị sửa đổi. Kết nối thất bại khi pool cạn kiệt.",
    "mode_desc_pat": "Tất cả các máy chủ bên trong chia sẻ pool IP công cộng thông qua cấp phát cổng duy nhất. Sự cạn kiệt cổng được hiển thị dưới dạng các kết nối bị hủy.",
