    "desc_strategy_dynamic": "Standard PAT cấp phát các cổng nguồn một cách động từng cái một khi các kết nối được mở. Giá trị ở đây đại diện cho việc sử dụng cổng đỉnh được mô hình hóa trên mỗi máy chủ để ước tính tổng công suất.",
    "desc_strategy_deterministic": "CGNAT cấp phát một khối cổng nguồn cố định, được dự trữ cho mỗi người đăng ký trước. Điều này đảm bảo tính khả dụng của cổng và giảm 99% chi phí syslog (chỉ ghi nhật ký cấp phát khối, không phải các phiên riêng lẻ), nhưng giới hạn tổng số người đăng ký trên mỗi IP công cộng.",
