    "warning_nat_oversubscribed": "CẢNH BÁO: Pool đã bị đăng ký vượt mức! Static/Dynamic NAT yêu cầu ánh xạ 1:1. Các máy chủ vượt quá kích thước pool sẽ không thể chuyển đổi.",
