    "scenario_overlap_title": "Kịch bản 1: Các Subnet chồng lấn (IPsec VPN)",
    "scenario_overlap_desc": "Hai mạng sử dụng cùng một dải riêng tư (vd: 192.168.1.0/24). Để giao tiếp mà không bị xung đột IP, cả hai bên phải thực hiện NAT. Máy chủ A chuyển đổi sang một IP trung gian và Máy chủ B chuyển đổi sang một IP trung gian.",
    "scenario_cgnat_title": "Kịch bản 2: Carrier-Grade NAT (CGNAT) đến NAT khách hàng",
    "scenario_cgnat_desc": "Nhà cung cấp dịch vụ cấp phát 100.64.0.0/10 (RFC 6598) cho WAN khách hàng. Khách hàng thực hiện NAT cục bộ (192.168.1.0/24 -> 100.64.1.2) và Nhà cung cấp thực hiện CGNAT (100.64.1.2 -> IP công cộng) để tiết kiệm không gian IPv4.",
