    "err_invalid_ip": "Định dạng địa chỉ IP không hợp lệ",
    "explanation_title": "Hiểu về NAT và PAT",
    "explanation_intro": "Network Address Translation (NAT) và Port Address Translation (PAT) là các kỹ thuật để ánh xạ một không gian địa chỉ IP sang một không gian khác, chủ yếu được sử dụng để bảo tồn các địa chỉ IPv4 công cộng hạn chế hoặc giải quyết các xung đột subnet.",
    "nat_expl_title": "1. NAT là gì?",
    "nat_expl_desc": "NAT chuyển đổi địa chỉ IP trên cơ sở 1-1. Nó có thể là Static (ánh xạ vĩnh viễn một IP riêng tư sang một IP công cộng, lý tưởng cho các máy chủ hướng ra công chúng) hoặc Dynamic (cấp phát một IP công cộng từ pool cho một máy chủ riêng tư theo yêu cầu. Khi tất cả các IP công cộng đã được chỉ định, các máy chủ tiếp theo sẽ bị chặn cho đến khi một IP được giải phóng). Số cổng không bị sửa đổi.",
    "pat_expl_title": "2. PAT (NAT Overload) gì?",
    "pat_expl_desc": "PAT (hoặc Port Address Translation / NAT Overload) chuyển đổi cả địa chỉ IP và số cổng nguồn trên cơ sở nhiều-đến-một (N-1). Nhiều máy chủ riêng tư chia sẻ một địa chỉ IP công cộng duy nhất bằng cách gán các cổng nguồn duy nhất (vd: 192.168.1.10:5000 và 192.168.1.11:5000 ánh xạ tới 203.0.113.10:1024 và 203.0.113.10:1025). Đây là phương pháp tiêu chuẩn cho các bộ định tuyến gia đình và truy cập internet doanh nghiệp.",
    "comparison_table_title": "Tóm tắt so sánh",
    "comp_header_feature": "Tính năng",
    "comp_header_nat": "NAT (1-1)",
    "comp_header_pat": "PAT (N-1 / Overload)",
