    "about_body": "iperf là một công cụ đo lường chủ động cho băng thông tối đa có thể đạt được trên mạng IP. Một host chạy như một server (người lắng nghe) và một host khác kết nối như một client để gửi (hoặc nhận) lưu lượng qua TCP, UDP hoặc SCTP, báo cáo băng thông, jitter và mất gói tin. iperf3 (file thực thi iperf3) là bản viết lại hiện đại với đầu ra JSON và các chế độ đảo ngược/hai chiều; iperf2 (file thực thi iperf) hỗ trợ nhiều client và mạnh hơn cho việc kiểm tra Wi-Fi và multicast. Hai phiên bản này KHÔNG tương thích với nhau — cả hai đầu phải chạy cùng một phiên bản.",
